import json
import re
from docx import Document

def replace_in_paragraph(para, data):
    text = para.text
    # Regex to find {{KEY}}
    pattern = r'\{\{([A-Z_]+)\}\}'
    matches = re.findall(pattern, text)

    if not matches:
        return

    new_text = text
    for key in matches:
        placeholder = '{{' + key + '}}'
        if key in data:
            new_text = new_text.replace(placeholder, str(data[key]))

    if new_text != text:
        # Clear runs and set new text in the first run to preserve paragraph style
        # Note: This puts all text in the first run's style.
        runs = para.runs
        if runs:
